import Vue from 'vue'
import Router from 'vue-router'

import Home from '@/views/Home.vue'
import ReportMissing from '@/views/ReportMissing.vue'
import ReportSighting from '@/views/ReportSighting.vue'
import MissingList from '@/views/MissingList.vue'
import MissingProfile from '@/views/MissingProfile.vue'
import Alerts from '@/views/Alerts.vue'
import Splash from '@/views/splash.vue'

// AUTH
import Login from '@/views/Login.vue'
import Register from '@/views/Register.vue'

import { supabase } from '@/supabase'

Vue.use(Router)

const router = new Router({
  mode: 'hash',  // REQUIRED FOR GITHUB PAGES
  routes: [
    { path: '/', name: 'Splash', component: Splash },

    { path: '/login', name: 'Login', component: Login },
    { path: '/register', name: 'Register', component: Register },

    { path: '/home', component: Home, meta: { requiresAuth: true } },
    { path: '/reportmissing', component: ReportMissing, meta: { requiresAuth: true } },
    { path: '/reportsighting', component: ReportSighting, meta: { requiresAuth: true } },
    { path: '/missing', component: MissingList, meta: { requiresAuth: true } },
    { path: '/missingp', component: MissingProfile, props: true, meta: { requiresAuth: true } },
    { path: '/alerts', component: Alerts, meta: { requiresAuth: true } }
  ]
})

// ---------------------------------------
// AUTH PROTECTION (SAFE FOR OLD SUPABASE SDK)
// ---------------------------------------
router.beforeEach(async (to, from, next) => {
  if (!to.meta.requiresAuth) {
    return next()
  }

  const session = supabase.auth.session()

  if (!session) {
    return next('/login')
  }

  next()
})

export default router
